    struct IoFundedBondSnapshot {
        uint256 purchased;
        uint256 principal;
        uint256 rewards;
        uint256 liquidityDetf;
        uint256 supply;
        uint256 backing;
        uint256 gonsPerUnit;
        uint256 userDetf;
        uint256 ownedLp;
